236	func (s *Store) Verify() (int, error) {
237		entries, err := s.List()
238		if err != nil {
239			return 0, err
240		}
241		for _, entry := range entries {
242			if err := s.verifyObject(entry); err != nil {
243				return 0, fmt.Errorf("verify %q: %w", entry.Name, err)
244			}
245		}
246		return len(entries), nil
247	}
248	
249	// verifyObject checks that the content object for entry exists and that its
250	// actual size and SHA-256 match the recorded metadata.
251	func (s *Store) verifyObject(entry Entry) error {
252		file, err := os.Open(s.objectPath(entry.Digest))
253		if err != nil {
254			return err
255		}
256		hash := sha256.New()
257		size, copyErr := io.Copy(hash, file)
258		closeErr := file.Close()
259		if copyErr != nil || closeErr != nil {
260			return errors.New("read failed")
261		}
262		if size != entry.Size || hex.EncodeToString(hash.Sum(nil)) != entry.Digest {
263			return errors.New("content mismatch")
264		}
265		return nil
266	}
267	
268	func (s *Store) load() (index, error) {
269		data, err := os.ReadFile(s.indexPath())
270		if err != nil {
271			return index{}, err
272		}
273		var idx index
274		if err := json.Unmarshal(data, &idx); err != nil {
275			return index{}, err
276		}
277		if idx.Entries == nil {
278			idx.Entries = map[string]Entry{}
279		}
280		return idx, nil
281	}
282	
283	func (s *Store) save(idx index) error {
284		data, err := json.MarshalIndent(idx, "", "  ")
285		if err != nil {
286			return err
287		}
288		data = append(data, '\n')
289		tmp, err := os.CreateTemp(s.root, ".index-*")
290		if err != nil {
291			return err
292		}
293		tmpName := tmp.Name()
294		defer os.Remove(tmpName)
295		if _, err := tmp.Write(data); err != nil {
296			tmp.Close()
297			return err
298		}
299		if err := tmp.Close(); err != nil {
300			return err
301		}
302		return os.Rename(tmpName, s.indexPath())
303	}
304	
305	func (s *Store) indexPath() string               { return filepath.Join(s.root, "index.json") }
306	func (s *Store) lockPath() string                { return filepath.Join(s.root, ".lock") }
